import type { Fact, WalkStep } from '@/app/demos/stage/types'

/** The demo runs at a fixed instant with UTC as the visitor's zone, so every value is reproducible. */
export const NOW = Date.UTC(2026, 9, 24, 9, 0, 0)
const DAY = 86_400_000
const UTC = 'UTC'

const pad = (value: number) => String(Math.abs(value)).padStart(2, '0')
const utcDay = (ms: number) => {
  const date = new Date(ms)
  return Date.UTC(date.getUTCFullYear(), date.getUTCMonth(), date.getUTCDate())
}

/** relativeTime and relativeDayLabel from the extension. */
const STEPS_REL: { limit: number; divisor: number; unit: Intl.RelativeTimeFormatUnit }[] = [
  { limit: 60, divisor: 1, unit: 'second' },
  { limit: 3_600, divisor: 60, unit: 'minute' },
  { limit: 86_400, divisor: 3_600, unit: 'hour' },
  { limit: 604_800, divisor: 86_400, unit: 'day' },
  { limit: 2_592_000, divisor: 604_800, unit: 'week' },
  { limit: 31_536_000, divisor: 2_592_000, unit: 'month' },
  { limit: Infinity, divisor: 31_536_000, unit: 'year' },
]
const relative = new Intl.RelativeTimeFormat('en', { numeric: 'auto' })
export function relativeDayLabel(ms: number, now = NOW): string {
  const days = Math.round((utcDay(ms) - utcDay(now)) / DAY)
  if (days !== 0 && Math.abs(days) <= 6) return relative.format(days, 'day')
  const diff = Math.round((ms - now) / 1000)
  const step = STEPS_REL.find((entry) => Math.abs(diff) < entry.limit)!
  return relative.format(Math.trunc(diff / step.divisor), step.unit)
}

