/* ---------- Difference ---------- */

export const FROM_TEXT = '2026-10-24 09:00'
export const TO_TEXT = '2026-12-18 09:00'
const TO = Date.UTC(2026, 11, 18, 9, 0, 0)

function addMonths(ms: number, amount: number): number {
  const date = new Date(ms)
  const target = new Date(
    Date.UTC(
      date.getUTCFullYear(),
      date.getUTCMonth() + amount,
      1,
      date.getUTCHours(),
      date.getUTCMinutes(),
    ),
  )
  const last = new Date(Date.UTC(target.getUTCFullYear(), target.getUTCMonth() + 1, 0)).getUTCDate()
  target.setUTCDate(Math.min(date.getUTCDate(), last))
  return target.getTime()
}

/** calendarDiff, worked in UTC. */
function calendarDiff(a: number, b: number) {
  const start = new Date(a)
  const end = new Date(b)
  let months =
    (end.getUTCFullYear() - start.getUTCFullYear()) * 12 + end.getUTCMonth() - start.getUTCMonth()
  let anchor = addMonths(a, months)
  while (months > 0 && anchor > b) anchor = addMonths(a, --months)
  let days = Math.round((utcDay(b) - utcDay(anchor)) / DAY)
  while (days > 0 && anchor + days * DAY > b) days -= 1
  const total = b - a
  const calendarDays = Math.round((utcDay(b) - utcDay(a)) / DAY) + 1
  let workingDays = 0
  for (let index = 0; index < calendarDays; index++) {
    const weekday = new Date(utcDay(a) + index * DAY).getUTCDay()
    if (weekday !== 0 && weekday !== 6) workingDays += 1
  }
  return {
    months,
    days,
    totalDays: Math.floor(total / DAY),
    totalWeeks: Math.floor((total / DAY / 7) * 10) / 10,
    totalHours: Math.floor(total / 3_600_000),
    totalMinutes: Math.floor(total / 60_000),
    totalSeconds: Math.floor(total / 1000),
    calendarDays,
    workingDays,
    weekendDays: calendarDays - workingDays,
  }
}

const diff = calendarDiff(NOW, TO)
const plural = (count: number, unit: string) => `${count} ${unit}${count === 1 ? '' : 's'}`
export const HEADLINE = [
  diff.months ? plural(diff.months, 'month') : '',
  diff.days ? plural(diff.days, 'day') : '',
]
  .filter(Boolean)
  .join(', ')
export const TOTALS = [
  { label: 'Total days', value: diff.totalDays },
  { label: 'Total weeks', value: diff.totalWeeks, decimals: 1 },
  { label: 'Total hours', value: diff.totalHours },
  { label: 'Total minutes', value: diff.totalMinutes },
  { label: 'Total seconds', value: diff.totalSeconds },
  { label: 'Calendar days', value: diff.calendarDays, hint: 'Counting both ends' },
  { label: 'Working days', value: diff.workingDays, hint: 'Monday to Friday', emphasis: true },
  { label: 'Weekend days', value: diff.weekendDays },
]

/* ---------- Zones ---------- */

const ZONES = [
  { id: 'UTC', label: 'UTC' },
  { id: 'America/New_York', label: 'New York' },
  { id: 'Europe/London', label: 'London' },
  { id: 'Asia/Kolkata', label: 'India (IST)' },
  { id: 'Asia/Tokyo', label: 'Tokyo' },
  { id: 'Australia/Sydney', label: 'Sydney' },
]
export const SHIFT = 6

export type Phase = 'night' | 'morning' | 'work' | 'evening'
const phase = (hour: number): Phase =>
  hour >= 9 && hour < 17
    ? 'work'
    : hour >= 6 && hour < 9
      ? 'morning'
      : hour >= 17 && hour < 22
        ? 'evening'
        : 'night'

function wall(ms: number, zone: string) {
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone: zone,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    hourCycle: 'h23',
  }).formatToParts(ms)
  const get = (type: string) => Number(parts.find((part) => part.type === type)?.value ?? 0)
  return {
    year: get('year'),
    month: get('month'),
    day: get('day'),
    hour: get('hour'),
    minute: get('minute'),
  }
}

export const formatOffset = (minutes: number) =>
  `${minutes >= 0 ? '+' : '-'}${pad(Math.floor(Math.abs(minutes) / 60))}:${pad(Math.abs(minutes) % 60)}`
const formatDelta = (minutes: number) => {
  const abs = Math.abs(minutes)
  return `${minutes > 0 ? '+' : '-'}${Math.floor(abs / 60)}h${abs % 60 ? ` ${abs % 60}m` : ''}`
}

function clocks(ms: number) {
  const ref = wall(ms, UTC)
  return ZONES.map((zone) => {
    const parts = wall(ms, zone.id)
    const offset = Math.round(
      (Date.UTC(parts.year, parts.month - 1, parts.day, parts.hour, parts.minute) -
        Math.floor(ms / 60_000) * 60_000) /
        60_000,
    )
    return {
      ...zone,
      offset,
      time: `${pad(parts.hour)}:${pad(parts.minute)}`,
      date: new Intl.DateTimeFormat('en-US', {
        timeZone: zone.id,
        weekday: 'short',
        day: 'numeric',
        month: 'short',
      }).format(ms),
      phase: phase(parts.hour),
      delta: zone.id === UTC ? 'Reference' : offset === 0 ? 'Same time' : formatDelta(offset),
      nextDay:
        Date.UTC(parts.year, parts.month - 1, parts.day) >
        Date.UTC(ref.year, ref.month - 1, ref.day),
    }
  }).sort((x, y) => x.offset - y.offset || x.label.localeCompare(y.label))
}

export const CLOCKS = clocks(NOW)
export const SHIFTED = clocks(NOW + SHIFT * 3_600_000)
export const SHIFT_LABEL = `Shifted ${formatDelta(SHIFT * 60)}`
export const MEETING = SHIFTED.filter((clock) => clock.phase === 'work').map((clock) => clock.label)

/* ---------- Cron ---------- */

export const CRON_DEFAULT = '30 9 * * 1-5'
export const CRON = '0 2 * * 0'
const FIELDS = [
  { name: 'minute', label: 'Minute', min: 0, max: 59 },
  { name: 'hour', label: 'Hour', min: 0, max: 23 },
  { name: 'day of month', label: 'Day of month', min: 1, max: 31 },
  { name: 'month', label: 'Month', min: 1, max: 12 },
  { name: 'day of week', label: 'Day of week', min: 0, max: 7 },
]
const DAY_NAMES = ['sun', 'mon', 'tue', 'wed', 'thu', 'fri', 'sat']
const WEEKDAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat']

/** parseCron for plain values, ranges and steps, which is all the demo expressions use. */
function parseCron(expression: string) {
  const parts = expression.trim().split(/\s+/)
  const fields = FIELDS.map((meta, index) => {
    const raw = parts[index]
    if (raw === '*') return { ...meta, raw, values: 'any' as const }
    const values = new Set<number>()
    for (const part of raw.split(',')) {
      const [range, step] = part.split('/')
      const [start, end] = range === '*' ? [meta.min, meta.max] : range.split('-').map(Number)
      const last = end ?? (step ? meta.max : start)
      for (let value = start; value <= last; value += Number(step ?? 1)) values.add(value)
    }
    return { ...meta, raw, values: [...values].sort((a, b) => a - b) }
  })
  const [minute, hour, dom, month, dow] = fields
  const time =
    minute.values !== 'any' &&
    hour.values !== 'any' &&
    minute.values.length === 1 &&
    hour.values.length === 1
      ? `At ${pad(hour.values[0])}:${pad(minute.values[0])}`
      : 'Runs at several times'
  const dayParts: string[] = []
  if (dom.values !== 'any') dayParts.push(`on day-of-month ${dom.values.join(', ')}`)
  if (month.values !== 'any') dayParts.push(`in month ${month.values.join(', ')}`)
  if (dow.values !== 'any')
    dayParts.push(
      `on ${[...new Set(dow.values.map((value) => value % 7))].map((value) => DAY_NAMES[value]).join(', ')}`,
    )
  const description = dayParts.length ? `${time}, ${dayParts.join(', ')}.` : `${time}, every day.`

  const shown = fields.map((field) =>
    field.values === 'any'
      ? 'Every value'
      : field.name === 'day of week'
        ? [...new Set(field.values.map((value) => value % 7))]
            .map((value) => WEEKDAYS[value])
            .join(', ')
        : field.values.join(', '),
  )

  const allows = (field: (typeof fields)[number], value: number) =>
    field.values === 'any' || field.values.includes(value)
  const dowAllows = (day: number) =>
    dow.values === 'any' || dow.values.some((value) => value % 7 === day)
  const both = dom.values !== 'any' && dow.values !== 'any'
  const runs: number[] = []
  const start = Math.floor(NOW / 60_000) * 60_000 + 60_000
  for (let day = utcDay(start); runs.length < 5; day += DAY) {
    const date = new Date(day)
    if (!allows(month, date.getUTCMonth() + 1)) continue
    const domOk = allows(dom, date.getUTCDate())
    const dowOk = dowAllows(date.getUTCDay())
    if (!(both ? domOk || dowOk : domOk && dowOk)) continue
    for (const h of hour.values === 'any' ? [...Array(24).keys()] : hour.values)
      for (const m of minute.values === 'any' ? [...Array(60).keys()] : minute.values) {
        const candidate = day + h * 3_600_000 + m * 60_000
        if (candidate >= start && runs.length < 5) runs.push(candidate)
      }
  }
  return {
    description,
    fields: fields.map((field, index) => ({
      label: field.label,
      raw: field.raw,
      shown: shown[index],
    })),
    runs: runs.map((run) => ({
      when: new Date(run).toLocaleString('en-US', {
        weekday: 'short',
        year: 'numeric',
        month: 'short',
        day: 'numeric',
        hour: '2-digit',
        minute: '2-digit',
        timeZone: UTC,
      }),
      relative: relativeDayLabel(run),
    })),
  }
}

export const CRON_START = parseCron(CRON_DEFAULT)
export const CRON_RESULT = parseCron(CRON)

